def clearDigits(s: str) -> str:
    # Use a stack to simulate letter removals
    stack = []
    for ch in s:
        if ch.isdigit():
            # Remove the closest non-digit to the left
            if stack:
                stack.pop()
            # Do not add the digit itself
        else:
            # Just push the letter
            stack.append(ch)
    # Join the remaining letters
    return ''.join(stack)
